	GetLoadBalances(context.Context, *connect.Request[v1.GetLoadBalancesRequest]) (*connect.Response[v1.GetLoadBalancesResponse], error)
	// 读取反向代理缓存配置。
	GetProxyCache(context.Context, *connect.Request[v1.GetProxyCacheRequest]) (*connect.Response[v1.ProxyCache], error)
	// 更新反向代理缓存配置。
	UpdateProxyCache(context.Context, *connect.Request[v1.UpdateProxyCacheRequest]) (*connect.Response[v1.UpdateProxyCacheResponse], error)
