	// 更新 Nginx 指令级配置。
	UpdateNginxScopeConfig(context.Context, *connect.Request[v1.UpdateNginxScopeConfigRequest]) (*connect.Response[v1.UpdateNginxScopeConfigResponse], error)
	// 读取网站的 HTTPS 配置。
	GetHTTPS(context.Context, *connect.Request[v1.GetWebsiteHTTPSRequest]) (*connect.Response[v1.WebsiteHTTPS], error)
	// 更新网站的 HTTPS 配置。
	UpdateHTTPS(context.Context, *connect.Request[v1.UpdateWebsiteHTTPSRequest]) (*connect.Response[v1.WebsiteHTTPS], error)
