	GetRewrite(context.Context, *connect.Request[v1.GetRewriteRequest]) (*connect.Response[v1.RewriteConfig], error)
	// 保存伪静态配置。
	UpdateRewrite(context.Context, *connect.Request[v1.UpdateRewriteRequest]) (*connect.Response[v1.UpdateRewriteResponse], error)
	// 读取重定向配置列表。
	GetRedirect(context.Context, *connect.Request[v1.GetRedirectRequest]) (*connect.Response[v1.GetRedirectResponse], error)
	// 保存重定向配置文件。
	UpdateRedirect(context.Context, *connect.Request[v1.UpdateRedirectRequest]) (*connect.Response[v1.UpdateRedirectResponse], error)
	// 读取网站 Nginx 配置文件。
	GetNginxFile(context.Context, *connect.Request[v1.GetWebsiteNginxFileRequest]) (*connect.Response[v1.FileEntry], error)
